CREATE OR REPLACE FUNCTION public.publish_monitor_quota_period(OUT p_start timestamp with time zone, OUT p_end timestamp with time zone, OUT p_limit integer)
 RETURNS record
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE cfg jsonb;anchor timestamp;now_utc timestamp:=clock_timestamp() AT TIME ZONE 'UTC';k integer;
BEGIN
