 IF jsonb_typeof(cfg) IS DISTINCT FROM 'object' OR coalesce(cfg->>'limit','') !~ '^[1-9][0-9]{0,6}$'
  OR jsonb_typeof(cfg->'periodAnchor') IS DISTINCT FROM 'string' THEN
